mapper.select:
select ct.id, ct.name, ct.color, ct.create_user, ct.create_time, (select count(*) from customer_tag_relation ctr where ctr.tag_id = ct.id and ctr.organization_id = #{orgId}) as customer_count from customer_tag ct where ct.organization_id = #{orgId}
and ct.name like concat('%', #{keyword}, '%')
order by ct.create_time desc

select ct.id, ct.name, ct.color
from customer_tag ct
inner join customer_tag_relation ctr on ct.id = ctr.tag_id
where ctr.customer_id = #{customerId}
and ctr.organization_id = #{orgId}
order by ctr.create_time desc

select count(*) from customer_tag
where name = #{name}
and organization_id = #{orgId}

    and id != #{excludeId}

mapper.delete:
delete from customer_tag_relation
where customer_id = #{customerId}
and organization_id = #{orgId}

delete from customer_tag_relation
where tag_id = #{tagId}
and organization_id = #{orgId}

mapper.select:
select count(distinct customer_id) from customer_tag_relation
where tag_id = #{tagId}
and organization_id = #{orgId}

select distinct ctr.customer_id
from customer_tag_relation ctr
where ctr.tag_id in

    #{tagId}

and ctr.organization_id = #{orgId}
